async def seed(session: AsyncSession) -> dict[str, int]:
    session.add(Source(id=1, platform="greenhouse", board_identifier="a", base_url="https://a"))
    await session.flush()
    ids = {}
    for i, (title, _) in enumerate(TITLES):
        job = Job(
            source_id=1,
            external_id=str(i),
            title=title,
            company=f"Company {i}",
            first_seen_at=T0,
            last_seen_at=T0,
            content_hash=str(i),
        )
        session.add(job)
        await session.flush()
        ids[title] = job.id
    await session.commit()
    return ids


async def test_levels_from_titles(session: AsyncSession) -> None:
    await seed(session)
    got = dict((await session.execute(select(Job.title, Job.seniority))).tuples().all())
    wrong = {t: (got[t], want) for t, want in TITLES if got[t] != want}
    assert not wrong, wrong


async def test_level_follows_title_changes(session: AsyncSession) -> None:
    await seed(session)
    job = await session.scalar(select(Job).where(Job.title == "Software Engineer"))
    assert job is not None
    job.title = "Senior Software Engineer"
    await session.commit()
    await session.refresh(job)
    assert job.seniority == "senior"


@pytest.fixture
async def client(
    session_factory: async_sessionmaker[AsyncSession],
) -> AsyncIterator[httpx.AsyncClient]:
    app.state.session_factory = session_factory
    pulse._cache.clear()
    transport = httpx.ASGITransport(app=app)
    async with httpx.AsyncClient(transport=transport, base_url="http://test") as c:
        yield c
    pulse._cache.clear()


def _count(level: str) -> int:
    return sum(want == level for _, want in TITLES)


async def test_api_filter_and_field(client: httpx.AsyncClient, session: AsyncSession) -> None:
    await seed(session)
    body = (await client.get("/jobs", params={"seniority": "internship", "size": 50})).json()
    assert body["total"] == _count("internship")
    assert {j["seniority"] for j in body["items"]} == {"internship"}
    assert (await client.get("/jobs", params={"seniority": "wizard"})).status_code == 422
    schema = (await client.get("/openapi.json")).json()
    params = {p["name"] for p in schema["paths"]["/jobs"]["get"]["parameters"]}
    assert "seniority" in params


async def test_search_page_filter(client: httpx.AsyncClient, session: AsyncSession) -> None:
    await seed(session)
    page = (await client.get("/", params={"seniority": "lead"})).text
    assert f"{_count('lead')} openings" in page
    assert '<option value="lead" selected>Lead</option>' in page
    assert '<span class="tag level">lead</span>' in page
    assert f"{len(TITLES)} openings" in (await client.get("/", params={"seniority": "x"})).text


async def test_mcp_filter(session: AsyncSession) -> None:
    await seed(session)
    found = await search_jobs(session, SearchJobsArgs(seniority="management"))
    assert found["total"] == _count("management")
    assert {j["seniority"] for j in found["jobs"]} == {"management"}


async def test_pulse_shares(client: httpx.AsyncClient, session: AsyncSession) -> None:
    await seed(session)
    p = await pulse.compute_pulse(session)
    shares = {str(b.key): b.count for b in p.seniority}
    assert shares == {level: _count(level) for level in shares}
    levels = ["internship", "junior", "mid", "senior", "lead", "management", "unknown"]
    assert list(shares) == levels
    page = (await client.get("/pulse")).text
    assert 'id="seniority"' in page
    assert 'href="/?seniority=senior"' in page
